#!/usr/bin/env bash
set -euo pipefail

# ==============================================================================
# RegOps 双通道并行解析（表元数据 + 码值字典）一键更新与推送脚本
# 用法：在本地 regops 仓库根目录下执行：
#   bash update_and_push_github.sh
# ==============================================================================

if [ ! -d "backend/app" ] || [ ! -d "frontend/src" ]; then
  echo "❌ 请在 regops 仓库根目录下运行此脚本（需包含 backend/app 和 frontend/src 目录）"
  exit 1
fi

echo "🚀 正在写入双通道并行解析前后端更新文件 (共 13 个文件)..."

mkdir -p "$(dirname "backend/app/spec_parser.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/spec_parser.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/spec_parser.py"
mkdir -p "$(dirname "backend/app/catalog.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/catalog.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/catalog.py"
mkdir -p "$(dirname "backend/app/extractors.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/extractors.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/extractors.py"
mkdir -p "$(dirname "backend/app/generic_ai.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/generic_ai.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/generic_ai.py"
mkdir -p "$(dirname "backend/app/structure_service.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/structure_service.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/structure_service.py"
mkdir -p "$(dirname "backend/app/metadata_service.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/metadata_service.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/metadata_service.py"
mkdir -p "$(dirname "backend/app/code_service.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/code_service.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/code_service.py"
mkdir -p "$(dirname "backend/app/api_v2/documents.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/api_v2/documents.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/api_v2/documents.py"
mkdir -p "$(dirname "backend/app/api_v2/metadata.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/api_v2/metadata.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/api_v2/metadata.py"
mkdir -p "$(dirname "backend/app/api_v2/code_sets.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/app/api_v2/code_sets.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/app/api_v2/code_sets.py"
mkdir -p "$(dirname "backend/tests/test_code_service.py")"
python3 -c "import base64, pathlib; pathlib.Path('backend/tests/test_code_service.py').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 backend/tests/test_code_service.py"
mkdir -p "$(dirname "frontend/src/pages/DocumentsPage.jsx")"
python3 -c "import base64, pathlib; pathlib.Path('frontend/src/pages/DocumentsPage.jsx').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 frontend/src/pages/DocumentsPage.jsx"
mkdir -p "$(dirname "frontend/src/pages/CodeSetsPage.jsx")"
python3 -c "import base64, pathlib; pathlib.Path('frontend/src/pages/CodeSetsPage.jsx').write_bytes(base64.b64decode(''))"
echo "  ✓ 已更新 frontend/src/pages/CodeSetsPage.jsx"

echo ""
echo "🧪 正在检查并运行后端单元测试 (如当前环境已安装 pytest)..."
if command -v pytest >/dev/null 2>&1; then
  (cd backend && pytest -q) || echo "⚠️ 本地 pytest 执行提示：请确认虚拟环境已激活"
elif [ -x "backend/.venv/bin/pytest" ]; then
  (cd backend && ./.venv/bin/pytest -q)
fi

echo ""
echo "📦 正在提交并推送到 GitHub (shawhang0336-blip/regops)..."
git add backend/app/spec_parser.py backend/app/catalog.py backend/app/extractors.py backend/app/generic_ai.py backend/app/structure_service.py backend/app/metadata_service.py backend/app/code_service.py backend/app/api_v2/documents.py backend/app/api_v2/metadata.py backend/app/api_v2/code_sets.py backend/tests/test_code_service.py frontend/src/pages/DocumentsPage.jsx frontend/src/pages/CodeSetsPage.jsx
if git diff --cached --quiet; then
  echo "ℹ️ 工作区已是最新内容，无需重复提交。"
else
  git commit -m "feat: unify document block discovery and parallel extraction for table metadata and code sets"
  CURRENT_BRANCH=$(git rev-parse --abbrev-ref HEAD)
  git push origin "$CURRENT_BRANCH"
  echo "✅ 已成功推送到远端分支: $CURRENT_BRANCH"
fi